# Synthesized [ev] for: Smart EV charging with solar peak matching
def execute_plan(params):
    params = dict(params or {})
    kwh = float(params.get('target_kwh', 8.0)); hour = int(params.get('schedule_hour', 14)); cap = float(params.get('max_price', 0.28)); peak = 0.52 if 16 <= hour <= 20 else (0.12 if (hour >= 22 or hour < 6) else 0.28); savings = round(max(0.0, (0.52 - peak)) * kwh, 2) if peak <= cap else 0.0
    return {'status': 'scheduled', 'requirement': params.get('note', ''), 'applied_hour': int(params.get('schedule_hour', 14)), 'eco_mode': bool(params.get('eco_mode', True)), 'savings_usd': float(savings)}
def handle(action, params):
    return {'executed_action': action, **execute_plan(params)}
